[CmdletBinding(SupportsShouldProcess = $true, ConfirmImpact = 'Low')]
param([string] $ConfigPath, [string] $OutputPath = ".\operatoros-output", [switch] $DryRun, [switch] $EnableTranscript, [string] $ScriptVersion = "1.0.0")
$OperatorOSFrameworkPath = Join-Path -Path $PSScriptRoot -ChildPath "..\..\content\scripts\framework\OperatorOS-ScriptFramework.psm1"; Import-Module $OperatorOSFrameworkPath -Force
function Invoke-OperatorOSRetry { param([scriptblock] $Operation, [int] $Attempts = 3) for ($i = 1; $i -le $Attempts; $i++) { try { return & $Operation } catch { if ($i -eq $Attempts) { throw }; Start-Sleep -Seconds ([Math]::Min(10, $i * 2)) } } }
$Context = New-OperatorOSExecutionContext -ScriptName "Security Audit Template" -SafetyMode Audit -ConfigPath $ConfigPath -DryRun:$DryRun -EnableTranscript:$EnableTranscript -OutputPath $OutputPath; Add-OperatorOSEvidence -Context $Context -Name "ScriptVersion" -Value $ScriptVersion
try { Assert-OperatorOSPowerShellVersion -MinimumVersion "5.1"; Assert-OperatorOSPermission -PermissionName "Security read access" -ValidationScript { $true }; $Results = Invoke-OperatorOSRetry { Invoke-OperatorOSOperation -Context $Context -Name "Collect security audit data" -Operation { @() } }; Add-OperatorOSEvidence -Context $Context -Name "Machine" -Value (Get-OperatorOSMachineInfo); Export-OperatorOSReport -Context $Context -Data @($Results) -Format Html,Csv,Json; Complete-OperatorOSExecution -Context $Context -FindingCount @($Results).Count } catch { Add-OperatorOSException -Context $Context -Exception $_.Exception -Operation "Security audit"; throw }
